export function projectCoord([lng, lat]: [number, number]): [number, number] {
  if (lat < 29.0) {
    const x = (lng - 122.7) * 42.0 + 575;
    const y = 710 - (lat - 24.0) * 42.0;
    return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
  }
  const x = (lng - 128.3) * 43.5 + 55;
  const latRad = (lat * Math.PI) / 180;
  const mercY = Math.log(Math.tan(Math.PI / 4 + latRad / 2)) * (180 / Math.PI);
  const mercMin = Math.log(Math.tan(Math.PI / 4 + (30.0 * Math.PI) / 360)) * (180 / Math.PI);
  const mercMax = Math.log(Math.tan(Math.PI / 4 + (45.7 * Math.PI) / 360)) * (180 / Math.PI);
  const y = 735 - ((mercY - mercMin) / (mercMax - mercMin)) * 705;
  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
}
